<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {api,message} from '../api/client'
import {loadBranding} from '../ui/branding'
const form=reactive<any>({}),ready=ref(false),loading=ref(false),error=ref(''),tab=ref('basic'),rules=ref('')
const gatewayFields=[['max_concurrency','网关最大并发',1,100000],['queue_size','推理队列容量',0,100000],['queue_timeout','推理等待秒数',1,3600],['nonstream_timeout','非流式 / 上游响应头超时秒数',1,600],['stream_idle_timeout','流空闲超时秒数',1,3600],['max_body_bytes','请求体上限（字节）',1024,10485760],['sticky_timeout','会话粘性秒数',1,86400],['health_check_interval','模型列表巡检间隔（0关闭）',0,86400],['failure_threshold','普通故障阈值',1,100],['cooldown_seconds','初始冷却秒数',1,3600]] as const
const securityFields=[['jwt_expire','Access Token有效秒数',60,86400],['refresh_days','Refresh有效天数',1,90],['login_max_attempts','账户失败登录上限',1,50],['login_lock_seconds','登录锁定秒数',30,86400]] as const
async function load(){loading.value=true;error.value='';try{Object.assign(form,(await api.get('/admin/settings')).data.data);rules.value=form.logging.redaction_rules.join('\n');ready.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){loading.value=true;try{form.logging.redaction_rules=rules.value.split('\n').map(x=>x.trim()).filter(Boolean);Object.assign(form,(await api.patch('/admin/settings',form)).data.data);await loadBranding();ElMessage.success('设置已保存，运行参数即时生效')}catch(e){ElMessage.error(message(e))}finally{loading.value=false}}
function image(event:Event,key:'logo'|'icon'){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.type!=='image/png'||file.size>256*1024){ElMessage.error('请选择不超过256KiB的PNG图片');return}const reader=new FileReader();reader.onload=()=>{form.basic[key]=String(reader.result)};reader.readAsDataURL(file)}
onMounted(load)
</script>
<template><PageHeader title="系统设置" description="超级管理员管理品牌、接入地址、网关与日志策略。"><el-button :loading="loading" @click="load">重新加载</el-button><el-button type="primary" :disabled="!ready" :loading="loading" @click="save">保存设置</el-button></PageHeader><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-if="ready" class="panel"><el-tabs v-model="tab"><el-tab-pane label="基础与品牌" name="basic"><el-form label-position="top"><el-form-item label="系统名称"><el-input v-model="form.basic.system_name" maxlength="80"/></el-form-item><div class="settings-grid"><el-form-item v-for="key in (['logo','icon'] as const)" :key="key" :label="key==='logo'?'系统Logo':'浏览器Icon'"><img v-if="form.basic[key]" :src="form.basic[key]" class="brand-preview"/><input type="file" accept="image/png" @change="image($event,key)"/><el-button text @click="form.basic[key]=''">清除</el-button></el-form-item></div><el-form-item label="系统URL"><el-input v-model="form.basic.system_url" placeholder="留空使用当前网站地址"/></el-form-item><el-form-item label="Public API Base URL"><el-input v-model="form.basic.public_api_base_url" placeholder="例如 https://gateway.example/v1；留空使用当前地址/v1"/></el-form-item><p class="muted">公开地址用于接入示例，浏览器管理请求继续访问当前网站。</p><el-form-item label="语言"><el-select v-model="form.basic.language"><el-option label="简体中文" value="zh-CN"/></el-select></el-form-item><el-form-item label="显示时区"><el-input v-model="form.basic.timezone" placeholder="Asia/Shanghai、UTC或有效IANA时区"/></el-form-item><p class="muted">显示时间使用此时区；Token配额周期与统计分桶仍按北京时间计算。</p></el-form></el-tab-pane><el-tab-pane label="网关与调度" name="gateway"><el-form label-position="top" class="settings-grid"><el-form-item v-for="[key,label,min,max] in gatewayFields" :key="key" :label="label"><el-input-number v-model="form.gateway[key]" :min="min" :max="max" :precision="0"/></el-form-item></el-form><p class="muted">降低并发上限不会中断正在执行的请求。鉴权错误立即将账号标记不可用；普通故障达到阈值后按冷却倍数重试。巡检只调用模型列表，0表示不自动请求上游。</p></el-tab-pane><el-tab-pane label="登录与安全" name="security"><el-form label-position="top" class="settings-grid"><el-form-item v-for="[key,label,min,max] in securityFields" :key="key" :label="label"><el-input-number v-model="form.security[key]" :min="min" :max="max"/></el-form-item><el-form-item label="仅HTTPS传输会话Cookie"><el-switch v-model="form.security.cookie_secure"/></el-form-item></el-form><p class="muted">HTTP访问时启用Secure Cookie将影响刷新与会话恢复；请在配置HTTPS后启用。Token时限用于新发放的Token，已发放Token按原到期时间校验。</p></el-tab-pane><el-tab-pane label="日志与隐私" name="logging"><el-form label-position="top"><el-form-item label="保存脱敏请求正文预览"><el-switch v-model="form.logging.save_request_body"/></el-form-item><el-form-item label="保存脱敏响应正文预览"><el-switch v-model="form.logging.save_response_body"/></el-form-item><p class="muted">默认关闭。开启后将保存客户正文，预览上限16KiB且仅管理员可读。认证头不保存，密码与密钥字段始终脱敏。流式响应只保存有限事件预览。</p><el-form-item label="附加脱敏正则（每行一条，最多20条）"><el-input v-model="rules" type="textarea" :rows="5"/></el-form-item><el-form-item label="调用 / 路由 / 审核日志保留天数"><el-input-number v-model="form.logging.retention_days" :min="366" :max="3650"/></el-form-item><p class="muted">至少366天以保留最长统计查询周期。后台分批清理过期记录；用量汇总与管理审计长期保留。</p></el-form></el-tab-pane></el-tabs></section></template>
<style scoped>.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 32px}.brand-preview{width:48px;height:48px;object-fit:contain;margin-right:16px}@media(max-width:700px){.settings-grid{grid-template-columns:1fr}}</style>
